41	function stableStringify(value: unknown): string {
42	  if (Array.isArray(value)) {
43	    return `[${value.map((entry) => stableStringify(entry)).join(",")}]`;
44	  }
45	  if (value && typeof value === "object") {
46	    const rec = value as Record<string, unknown>;
47	    return `{${Object.keys(rec).sort().map((key) => `${JSON.stringify(key)}:${stableStringify(rec[key])}`).join(",")}}`;
48	  }
49	  return JSON.stringify(value);
50	}
