52	function sanitizeServiceKeySegment(value: string, fallback: string): string {
53	  const normalized = value
54	    .trim()
55	    .toLowerCase()
56	    .replace(/[^a-z0-9._-]+/g, "-")
57	    .replace(/-+/g, "-")
58	    .replace(/^-+|-+$/g, "");
59	  return normalized || fallback;
60	}
